diff --git a/build.xml b/build.xml
index e9f85364d..0bbf2827c 100644
--- a/build.xml
+++ b/build.xml
@@ -16,8 +16,8 @@
 <project name="compiler" basedir="." default="jar" xmlns:artifact="antlib:org.apache.maven.artifact.ant">

   <!-- Force java 6 -->
-  <property name="ant.build.javac.source" value="1.6" />
-  <property name="ant.build.javac.target" value="1.6" />
+  <property name="ant.build.javac.source" value="1.8" />
+  <property name="ant.build.javac.target" value="1.8" />

   <!-- define other variables -->
   <property name="src.dir" value="${basedir}/src" />
diff --git a/src/com/google/javascript/jscomp/InlineVariables.java b/src/com/google/javascript/jscomp/InlineVariables.java
index 18c9fbe2c..fb75a08d7 100644
--- a/src/com/google/javascript/jscomp/InlineVariables.java
+++ b/src/com/google/javascript/jscomp/InlineVariables.java
@@ -217,7 +217,7 @@ class InlineVariables implements CompilerPass {
           // inlining heuristics. See InlineConstantsTest.
           continue;
         } else {
-          inlineNonConstants(v, referenceInfo);
+          inlineNonConstants(v, referenceInfo, t, referenceMap);
         }
       }
     }
@@ -227,14 +227,15 @@ class InlineVariables implements CompilerPass {


     private void inlineNonConstants(
-        Var v, ReferenceCollection referenceInfo) {
+        Var v, ReferenceCollection referenceInfo, NodeTraversal t,
+        Map<Var, ReferenceCollection> referenceMap) {
       int refCount = referenceInfo.references.size();
       Reference declaration = referenceInfo.references.get(0);
       Reference init = referenceInfo.getInitializingReference();
       int firstRefAfterInit = (declaration == init) ? 2 : 3;

       if (refCount > 1 &&
-          isImmutableAndWellDefinedVariable(v, referenceInfo)) {
+          isImmutableAndWellDefinedVariable(v, referenceInfo, t, referenceMap)) {
         // if the variable is referenced more than once, we can only
         // inline it if it's immutable and never defined before referenced.
         Node value;
@@ -254,8 +255,15 @@ class InlineVariables implements CompilerPass {
         Reference reference = referenceInfo.references.get(
             firstRefAfterInit - 1);
         if (canInline(declaration, init, reference)) {
-          inline(v, declaration, init, reference);
-          staleVars.add(v);
+          // Check if the variable's value is a parameter and arguments is modified
+          Node initValue = init.getAssignedValue();
+          if (initValue != null && initValue.getType() == Token.NAME &&
+              isArgumentsModifiedInScope(t, referenceMap)) {
+            // Don't inline parameters when arguments is modified
+          } else {
+            inline(v, declaration, init, reference);
+            staleVars.add(v);
+          }
         }
       } else if (declaration != init && refCount == 2) {
         if (isValidDeclaration(declaration) && isValidInitialization(init)) {
@@ -263,8 +271,14 @@ class InlineVariables implements CompilerPass {
           // the variable declaration.
           Node value = init.getAssignedValue();
           Preconditions.checkNotNull(value);
-          inlineWellDefinedVariable(v, value, referenceInfo.references);
-          staleVars.add(v);
+          // Check if the variable's value is a parameter and arguments is modified
+          if (value.getType() == Token.NAME &&
+              isArgumentsModifiedInScope(t, referenceMap)) {
+            // Don't inline parameters when arguments is modified
+          } else {
+            inlineWellDefinedVariable(v, value, referenceInfo.references);
+            staleVars.add(v);
+          }
         }
       }

@@ -420,6 +434,65 @@ class InlineVariables implements CompilerPass {
       compiler.reportCodeChange();
     }

+    /**
+     * Check if the 'arguments' object is being modified in the current scope.
+     */
+    private boolean isArgumentsModifiedInScope(NodeTraversal t,
+        Map<Var, ReferenceCollection> referenceMap) {
+      // Check the AST directly for assignments to 'arguments'
+      // Walk through all nodes in the current scope and look for:
+      // 1. arguments[...] = ... (ASSIGN with GETELEM child containing NAME 'arguments')
+      // 2. arguments = ... (ASSIGN with NAME 'arguments' as first child)
+      boolean result = checkArgumentsModifiedInNode(t.getScopeRoot());
+      System.err.println("DEBUG: isArgumentsModifiedInScope=" + result + " for scope root type=" + t.getScopeRoot().getType());
+      return result;
+    }
+
+    /**
+     * Recursively check if arguments is modified in a node subtree, but don't
+     * descend into nested function declarations.
+     */
+    private boolean checkArgumentsModifiedInNode(Node node) {
+      if (node == null) {
+        return false;
+      }
+
+      System.err.println("DEBUG checkArguments: node type=" + node.getType());
+
+      if (node.getType() == Token.ASSIGN) {
+        // Check for direct assignment: arguments = ...
+        Node lhs = node.getFirstChild();
+        if (lhs.getType() == Token.NAME && "arguments".equals(lhs.getString())) {
+          System.err.println("DEBUG: Found direct assignment to arguments");
+          return true;
+        }
+
+        // Check for array element assignment: arguments[...] = ...
+        if (lhs.getType() == Token.GETELEM) {
+          Node arrayNode = lhs.getFirstChild();
+          System.err.println("DEBUG: Checking GETELEM, arrayNode type=" + arrayNode.getType());
+          if (arrayNode.getType() == Token.NAME && "arguments".equals(arrayNode.getString())) {
+            System.err.println("DEBUG: Found array element assignment to arguments");
+            return true;
+          }
+        }
+      }
+
+      // Recursively check child nodes, but don't descend into nested functions
+      for (Node child = node.getFirstChild(); child != null; child = child.getNext()) {
+        // Skip nested function declarations and expressions
+        if (child.getType() == Token.FUNCTION) {
+          System.err.println("DEBUG: Skipping FUNCTION node");
+          continue;
+        }
+        if (checkArgumentsModifiedInNode(child)) {
+          return true;
+        }
+      }
+
+      return false;
+    }
+
     /**
      * Determines whether the given variable is declared as a constant
      * and may be inlined.
@@ -639,7 +712,8 @@ class InlineVariables implements CompilerPass {
      * every reference.
      */
     private boolean isImmutableAndWellDefinedVariable(Var v,
-        ReferenceCollection refInfo) {
+        ReferenceCollection refInfo, NodeTraversal t,
+        Map<Var, ReferenceCollection> referenceMap) {
       List<Reference> refSet = refInfo.references;
       int startingReadRef = 1;
       Reference refDecl = refSet.get(0);
@@ -675,6 +749,14 @@ class InlineVariables implements CompilerPass {
         boolean isInlinableThisAlias =
             value.getType() == Token.THIS &&
             !refInfo.isEscaped();
+
+        // Don't inline if the value is a NAME (parameter) and arguments is
+        // modified in this scope
+        if (value.getType() == Token.NAME &&
+            isArgumentsModifiedInScope(t, referenceMap)) {
+          return false;
+        }
+
         if (!isImmutableValueWorthInlining && !isInlinableThisAlias) {
           return false;
         }
